-- ============================================================================
-- Clyo Nutri v47: VERIFICAÇÃO (somente leitura), depois do atualizacao-v47-completa.sql
-- BANCO: o script usa o banco selecionado no phpMyAdmin. Se o phpMyAdmin trocar o banco ativo para o
-- information_schema (era o que causava o erro #1109) ou se nenhum banco estiver selecionado, ele usa o banco
-- reserva da linha SET @db_reserva logo abaixo. Para outro banco, troque só essa linha. A coluna "banco" do
-- resultado mostra em qual banco o script rodou. Revisado na v49.
-- Cada linha deve dar OK. Não altera nada. MySQL 5.7 e 8.
-- ============================================================================
SET @db_reserva = 'maic6824_Clyonutri2';
SET @db = IF(DATABASE() IS NULL OR DATABASE() IN ('information_schema','mysql','performance_schema','sys'), @db_reserva, DATABASE());
SET @c = CONCAT('SELECT ''banco'' AS item, @db AS resultado
UNION ALL SELECT ''colunas da migração 66 (17)'', IF(((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = @db AND TABLE_NAME = ''exam_regulatory_policies'' AND COLUMN_NAME IN (''change_summary'')) + (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = @db AND TABLE_NAME = ''exam_catalog'' AND COLUMN_NAME IN (''clinic_id'', ''origin'', ''validation_status'', ''submitted_by_user_id'', ''validated_by_user_id'', ''validated_at'', ''validation_note'', ''standard_code_system'', ''standard_code'', ''clinical_review_status'', ''clinical_reviewed_by'', ''clinical_reviewed_at'')) + (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = @db AND TABLE_NAME = ''exam_requests'' AND COLUMN_NAME IN (''appointment_id'', ''supersedes_request_id'', ''root_request_id'', ''version_number''))) = 17, ''OK'', ''FALHA'')
UNION ALL SELECT ''tabela exam_favorites'', IF((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = @db AND TABLE_NAME = ''exam_favorites'') = 1, ''OK'', ''FALHA'')
UNION ALL SELECT ''índices (4)'', IF(((SELECT COUNT(DISTINCT INDEX_NAME) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = @db AND TABLE_NAME = ''exam_catalog'' AND INDEX_NAME = ''idx_exam_catalog_clinic_validation'') + (SELECT COUNT(DISTINCT INDEX_NAME) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = @db AND TABLE_NAME = ''exam_favorites'' AND INDEX_NAME = ''uq_exam_favorites_user_exam'') + (SELECT COUNT(DISTINCT INDEX_NAME) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = @db AND TABLE_NAME = ''exam_requests'' AND INDEX_NAME = ''idx_exam_requests_appointment'') + (SELECT COUNT(DISTINCT INDEX_NAME) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = @db AND TABLE_NAME = ''exam_requests'' AND INDEX_NAME = ''idx_exam_requests_root'')) = 4, ''OK'', ''FALHA'')
UNION ALL SELECT ''favorito único por nutricionista e exame'', IF((SELECT COUNT(DISTINCT INDEX_NAME) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = @db AND TABLE_NAME = ''exam_favorites'' AND INDEX_NAME = ''uq_exam_favorites_user_exam'' AND NON_UNIQUE = 0) = 1, ''OK'', ''FALHA'')
UNION ALL SELECT ''ids novos em BIGINT(20)'', IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = @db AND TABLE_NAME = ''exam_requests'' AND COLUMN_NAME IN (''appointment_id'',''supersedes_request_id'',''root_request_id'') AND COLUMN_TYPE = ''bigint(20)'') = 3, ''OK'', ''FALHA'')
UNION ALL SELECT ''catálogo existente continua geral e validado'', IF((SELECT COUNT(*) FROM `', @db, '`.`exam_catalog` WHERE `clinic_id` IS NULL AND `validation_status` = ''approved'' AND `origin` = ''curated'') >= 22, ''OK'', ''FALHA'')
UNION ALL SELECT ''solicitações existentes na versão 1'', IF((SELECT COUNT(*) FROM `', @db, '`.`exam_requests` WHERE `version_number` <> 1 AND `supersedes_request_id` IS NULL) = 0, ''OK'', ''FALHA'')
UNION ALL SELECT ''migração 66 registrada uma vez'', IF((SELECT COUNT(*) FROM `', @db, '`.`migrations` WHERE `migration` = ''2026_10_29_000066_exam_catalog_favorites_versions_and_links'') = 1, ''OK'', ''FALHA'')
UNION ALL SELECT ''sem chave estrangeira nas tabelas de exames'', IF((SELECT COUNT(*) FROM information_schema.REFERENTIAL_CONSTRAINTS WHERE CONSTRAINT_SCHEMA = @db AND TABLE_NAME IN (''exam_regulatory_policies'',''exam_catalog'',''exam_requests'',''exam_request_items'',''exam_audit_logs'',''exam_favorites'')) = 0, ''OK'', ''FALHA'')');
PREPARE stmt_c FROM @c; EXECUTE stmt_c; DEALLOCATE PREPARE stmt_c;
